package com.chahinaz.pos.operations;import com.chahinaz.pos.sales.SaleItem;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;@Entity @Table(name="sale_return_item")public class SaleReturnItem{@Id public UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="return_id")public SaleReturn saleReturn;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="sale_item_id")public SaleItem saleItem;@Column(nullable=false)public int quantity;@Column(name="amount_usd",nullable=false,precision=12,scale=2)public BigDecimal amountUsd;@Column(nullable=false)public boolean restockable;protected SaleReturnItem(){}public SaleReturnItem(SaleReturn r,SaleItem i,int q,BigDecimal amount,boolean restock){id=UUID.randomUUID();saleReturn=r;saleItem=i;quantity=q;amountUsd=amount;restockable=restock;}}
